    "final_answer": "$x = -2 \\text{ of } x = 5$",
    "verify_code": "import sympy as sp\nx = sp.Symbol('x')\neq = sp.Eq(x**2 - 3*x - 10, 0)\nsolutions = sp.solve(eq, x)\nprint(sorted(solutions))",
